import{_ as a}from"./chunks/uavcan_wiring.0Ml-olhd.js";import{_ as r,o as t,c as n,al as i,j as e,a as s}from"./chunks/framework.7vp1BMOE.js";const A=JSON.parse('{"title":"CAN (DroneCAN & Cyphal)","description":"","frontmatter":{},"headers":[],"relativePath":"en/can/index.md","filePath":"en/can/index.md"}'),l={name:"en/can/index.md"};function c(h,o,p,d,u,f){return t(),n("div",null,[...o[0]||(o[0]=[i('<h1 id="can-dronecan-cyphal" tabindex="-1">CAN (DroneCAN &amp; Cyphal) <a class="header-anchor" href="#can-dronecan-cyphal" aria-label="Permalink to &quot;CAN (DroneCAN &amp; Cyphal)&quot;">​</a></h1><p><a href="https://en.wikipedia.org/wiki/CAN_bus" target="_blank" rel="noreferrer">Controller Area Network (CAN)</a> is a robust wired network that allows drone components such as flight controller, ESCs, sensors, and other peripherals, to communicate with each other.</p><p>It is particularly recommended on larger vehicles.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>CAN it is designed to be democratic and uses differential signaling. For this reason it is very robust even over longer cable lengths (on large vehicles), and avoids a single point of failure. CAN also allows status feedback from peripherals and convenient firmware upgrades over the bus.</p><p>PX4 has the ability to track and log detailed information from CAN devices, including firmware versions, hardware versions, and serial numbers. This enables unique identification and lifecycle tracking of hardware connected to the flight controller. See <a href="./../debug/asset_tracking">Asset Tracking</a> for more information.</p><p>PX4 supports two software protocols for communicating with CAN devices:</p><ul><li><a href="./../dronecan/">DroneCAN</a>: PX4 recommends this for most common setups. It is well supported by PX4, is a mature product with extensive peripheral support, and has had years of testing.</li><li><a href="https://opencyphal.org" target="_blank" rel="noreferrer">Cyphal</a>: PX4 support is a &quot;work in progress&quot;. Cyphal is a much newer protocol which allows more flexibility and configuration, especially on larger and more complex vehicles. It has not yet seen significant adoption.</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Both DroneCAN and Cyphal originate from an earlier project named UAVCAN. In 2022 the project split into two: the original version of UAVCAN (UAVCAN v0) was renamed to DroneCAN, and the newer UAVCAN v1 was renamed Cyphal. The differences between the two protocols are outlined in <a href="https://forum.opencyphal.org/t/cyphal-vs-dronecan/1814" target="_blank" rel="noreferrer">Cyphal vs. DroneCAN</a>.</p></div><p>PX4 does not support other CAN software protocols for drones such as KDECAN (at time of writing).</p><h2 id="wiring" tabindex="-1">Wiring <a class="header-anchor" href="#wiring" aria-label="Permalink to &quot;Wiring&quot;">​</a></h2><p>The wiring for CAN networks is the same for both DroneCAN and Cyphal/CAN (in fact, for all CAN networks).</p><p>Devices within a network are connected in a <em>daisy-chain</em> in any order (this differs from UARTs peripherals, where you attach just one component per port).</p><div class="warning custom-block"><p class="custom-block-title">Don&#39;t connect each CAN peripheral to a separate CAN port!</p><p>Unlike UARTs, CAN peripherals are designed to be daisy chained, with additional ports such as <code>CAN2</code> used for <a href="#redundancy">redundancy</a>.</p></div><p>At either end of the chain, a 120Ω termination resistor should be connected between the two data lines. Flight controllers and some GNSS modules have built in termination resistors for convenience, thus should be placed at opposite ends of the chain. Otherwise, you can use a termination resistor such as <a href="https://shop.zubax.com/products/uavcan-micro-termination-plug?variant=6007985111069" target="_blank" rel="noreferrer">this one from Zubax Robotics</a>, or solder one yourself if you have access to a JST-GH crimper.</p><p>The following diagram shows an example of a CAN bus connecting a flight controller to 4 CAN ESCs and a GNSS. It includes a redundant bus connected to <code>CAN 2</code>.</p><p><img src="'+a+'" alt="CAN Wiring"></p><p>The diagram does not show any power wiring. Refer to your manufacturer instructions to confirm whether components require separate power or can be powered from the CAN bus itself.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>For more information, see <a href="https://wiki.zubax.com/public/cyphal/CyphalCAN-device-interconnection?pageId=2195476" target="_blank" rel="noreferrer">Cyphal/CAN device interconnection</a> (kb.zubax.com). While the article is written with the Cyphal protocol in mind, it applies equally to DroneCAN hardware and any other CAN setup. For more advanced scenarios, consult with <a href="https://forum.opencyphal.org/t/on-can-bus-topology-and-termination/1685" target="_blank" rel="noreferrer">On CAN bus topology and termination</a>.</p></div><h3 id="connectors" tabindex="-1">Connectors <a class="header-anchor" href="#connectors" aria-label="Permalink to &quot;Connectors&quot;">​</a></h3><p>Pixhawk standard compatible CAN devices use 4 pin JST-GH connectors for CAN. Two connectors are used for input and output when wiring in a chain (except for flight controllers and some GNSS devices with builtin termination, which only have a single JST-GH connector).</p><p>Other (non-Pixhawk compatible) devices may use different connectors. However, as long as the device firmware supports DroneCAN or Cyphal, it can be used.</p><h3 id="redundancy" tabindex="-1">Redundancy <a class="header-anchor" href="#redundancy" aria-label="Permalink to &quot;Redundancy&quot;">​</a></h3><p>DroneCAN and Cyphal/CAN support using a second (redundant) CAN interface. This is completely optional but increases the robustness of the connection.</p><p>Pixhawk flight controllers come with 2 CAN interfaces; if your peripherals support 2 CAN interfaces as well, it is recommended to wire both up for increased safety.</p><h3 id="flight-controllers-with-multiple-can-ports" tabindex="-1">Flight Controllers with Multiple CAN Ports <a class="header-anchor" href="#flight-controllers-with-multiple-can-ports" aria-label="Permalink to &quot;Flight Controllers with Multiple CAN Ports&quot;">​</a></h3><p><a href="./../flight_controller/">Flight Controllers</a> may have up to three independent CAN ports, such as <code>CAN1</code>, <code>CAN2</code>, <code>CAN3</code> (neither DroneCAN or Cyphal support more than three). Note that you can&#39;t have both DroneCAN and Cyphal running on PX4 at the same time.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>You only <em>need</em> one CAN port to support an arbitrary number of CAN devices using a particular CAN protocol. Don&#39;t connect each CAN peripheral to a separate CAN port!</p></div><p>Generally you&#39;ll daisy all CAN peripherals off a single port, and if there is more than one CAN port, use the second one for <a href="#redundancy">redundancy</a>. If there are three ports, you might use the remaining network for devices that support another CAN protocol.</p><p>The documentation for your flight controller should indicate which ports are supported/enabled. At runtime you can check what DroneCAN ports are enabled and their status using the following command on the <a href="./../debug/mavlink_shell">MAVLink Shell</a> (or some other console):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uavcan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><p>Note that you can also check the number of supported CAN interfaces for a board by searching for <code>CONFIG_BOARD_UAVCAN_INTERFACES</code> in its <a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/px4/fmu-v6xrt/default.px4board#" target="_blank" rel="noreferrer">default.px4board</a> configuration file.</p><h2 id="firmware" tabindex="-1">Firmware <a class="header-anchor" href="#firmware" aria-label="Permalink to &quot;Firmware&quot;">​</a></h2><p>CAN peripherals may run proprietary or open source firmware (check manufacturer guides to confirm the required setup).</p><p>PX4 can be built to run as open-source DroneCAN firmware on supported CAN hardware. See <a href="./../dronecan/px4_cannode_fw">PX4 DroneCAN Firmware</a> for more information.</p><h2 id="support-and-configuration" tabindex="-1">Support and Configuration <a class="header-anchor" href="#support-and-configuration" aria-label="Permalink to &quot;Support and Configuration&quot;">​</a></h2><p><a href="./../dronecan/">DroneCAN Setup and Configuration</a></p><p><a href="./../dronecan/px4_cannode_fw">PX4 DroneCAN Firmware</a></p><h2 id="videos" tabindex="-1">Videos <a class="header-anchor" href="#videos" aria-label="Permalink to &quot;Videos&quot;">​</a></h2><h3 id="dronecan" tabindex="-1">DroneCAN <a class="header-anchor" href="#dronecan" aria-label="Permalink to &quot;DroneCAN&quot;">​</a></h3><p>Intro to DroneCAN (UAVCANv0) and practical example with setup in QGroundControl:</p>',41),e("lite-youtube",{videoid:"IZMTq9fTiOM",title:"Intro to DroneCAN (UAVCANv0) and practical example with setup in QGroundControl"},null,-1),e("h3",{id:"cyphal",tabindex:"-1"},[s("Cyphal "),e("a",{class:"header-anchor",href:"#cyphal","aria-label":'Permalink to "Cyphal"'},"​")],-1),e("p",null,"UAVCAN v1 for drones (Cyphal) — PX4 Developer Summit Virtual 2020",-1),e("lite-youtube",{videoid:"6Bvtn_g8liU",title:"UAVCAN v1 for drones — PX4 Developer Summit Virtual 2020"},null,-1),e("hr",null,null,-1),e("p",null,"Getting started using UAVCAN v1 with PX4 on the NXP UAVCAN Board — PX4 Developer Summit Virtual 2020",-1),e("lite-youtube",{videoid:"MwdHwjaXYKs",title:"Getting started using UAVCAN v1 with PX4 on the NXP UAVCAN Board"},null,-1),e("hr",null,null,-1),e("p",null,"UAVCAN: a highly dependable publish-subscribe protocol for hard real-time intra-vehicular networking — PX4 Developer Summit Virtual 2019",-1),e("lite-youtube",{videoid:"MBtROivYPik",title:"UAVCAN: a highly dependable publish-subscribe protocol for hard ..."},null,-1)])])}const b=r(l,[["render",c]]);export{A as __pageData,b as default};
